	fixture := newManifestFixture(t, 60*24*time.Hour, 45*24*time.Hour)
	fixture.writeCandidate(t, fixture.manifest)
	candidateWire, err := os.ReadFile(fixture.candidatePath)
	if err != nil {
		t.Fatal(err)
	}
