		SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: publicWire, Capabilities: capabilities,
	}, issuedAt, expiresAt, root)
	if err != nil {
		t.Fatal(err)
	}
	return grant
}

