func (c command) verifyBootstrapAnchorAt(args []string, now time.Time) error {
	flags := flag.NewFlagSet("verify-anchor", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	anchorPath := flags.String("anchor", "", "canonical root-signed deployment bootstrap anchor envelope")
	identityPath := flags.String("identity", "", "canonical version-1 baked identity JSON")
	var rootPaths stringListFlag
	flags.Var(&rootPaths, "root-key", "trusted root Ed25519 public key PEM (repeatable)")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *anchorPath == "" || *identityPath == "" || flags.NArg() != 0 {
		return errors.New("verify-anchor requires --anchor, --identity, and at least one --root-key")
	}
	if len(rootPaths) == 0 || len(rootPaths) > bootstrapstart.MaxRootFiles {
		return fmt.Errorf("verify-anchor requires between 1 and %d --root-key files", bootstrapstart.MaxRootFiles)
	}
	verified, _, err := loadVerifiedBootstrapAnchor(*anchorPath, *identityPath, rootPaths, now)
	if err != nil {
		return err
	}
	anchor := verified.Anchor()
	grant, err := verified.LedgerDelegation()
	if err != nil {
		return err
	}
	output := verifiedBootstrapAnchorOutput{
		SchemaVersion: bootstrap.BootstrapAnchorSchemaVersion, AnchorSHA256: verified.Digest(),
		DeploymentID: anchor.DeploymentID, Environment: anchor.Environment, ClusterID: anchor.ClusterID,
		Cell: anchor.Cell, OCIRegion: anchor.OCIRegion, ControllerSlots: anchor.ControllerSlots,
		StorageDomain: anchor.StorageDomain, InitialRegionIntentGeneration: anchor.InitialRegionIntentGeneration,
		InitialRegionIntentSHA256: anchor.InitialRegionIntentSHA256, LedgerDelegationSubjectKeyID: grant.SubjectKeyID(),
		IssuedAt: verified.IssuedAt(), ExpiresAt: verified.ExpiresAt(),
	}
	encoded, err := trust.EncodePayload(output)
	if err != nil {
		return fmt.Errorf("encode verified bootstrap anchor summary: %w", err)
	}
	if _, err := c.output.Write(append(encoded, '\n')); err != nil {
		return fmt.Errorf("write verified bootstrap anchor summary: %w", err)
	}
	return nil
}

load_anchor.text:
func loadVerifiedBootstrapAnchor(anchorPath, identityPath string, rootPaths []string, now time.Time) (
	bootstrap.VerifiedBootstrapAnchor, trust.Keyring, error,
) {
	identityWire, err := readBoundedRegular(identityPath, 4<<10)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("read fixed bootstrap identity: %w", err)
	}
	var identity bootstrapstart.BakedIdentity
	if err := protocol.DecodeStrict(identityWire, &identity, 4<<10); err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("decode fixed bootstrap identity: %w", err)
	}
	if identity.SchemaVersion != 1 {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, errors.New("fixed bootstrap identity schemaVersion must be 1")
	}
	canonical, err := protocol.EncodeJSON(identity)
	if err != nil || !bytes.Equal(identityWire, canonical) {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, errors.New("fixed bootstrap identity must be canonical JSON")
	}
	expected := identity.AnchorExpectation()
	rootKeys := make([]ed25519.PublicKey, 0, len(rootPaths))
	rootBytes := 0
	for _, path := range rootPaths {
		wire, err := readBoundedRegular(path, bootstrapstart.MaxRootBytes)
		if err != nil {
			return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, err
		}
		rootBytes += len(wire)
		if rootBytes > bootstrapstart.MaxRootsTotal {
			return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("bootstrap root key files exceed %d aggregate bytes", bootstrapstart.MaxRootsTotal)
		}
		publicKey, err := parseRootPublicKey(wire)
		if err != nil {
			return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, err
		}
		rootKeys = append(rootKeys, publicKey)
	}
	roots, err := trust.ParseKeyring(rootKeys...)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("parse root trust set: %w", err)
	}
	anchorWire, err := readBoundedRegular(anchorPath, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("read bootstrap anchor: %w", err)
	}
	envelope, err := trust.DecodeEnvelope(anchorWire)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("decode bootstrap anchor: %w", err)
	}
	now = now.Round(0).UTC()
	verified, err := bootstrap.VerifyBootstrapAnchor(envelope, roots, expected, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("verify current bootstrap anchor: %w", err)
	}
	return verified, roots, nil
}

sign_ledger.text:
func (c command) signLedgerDelegationAt(args []string, now time.Time) error {
	flags := flag.NewFlagSet("sign-ledger-delegation", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	deploymentID := flags.String("deployment", "", "reviewed deployment identity")
	cell := flags.String("cell", "", "reviewed region cell: GRU, SFO, or FRA")
	environment := flags.String("environment", "", "reviewed environment: production or canary")
	var slots stringListFlag
	flags.Var(&slots, "slot", "reviewed controller slot, in ascending order (repeatable)")
	signerPublicPath := flags.String("signer-public-key", "", "delegated ledger signer Ed25519 public key PEM")
	rootPublicPath := flags.String("root-key", "", "offline root Ed25519 public key PEM")
	rootPrivatePath := flags.String("signing-key", "", "owner-only offline root Ed25519 PKCS#8 private key PEM")
	outputPath := flags.String("out", "", "new canonical signed ledger delegation envelope")
	issuedAtText := flags.String("issued-at", "", "explicit UTC RFC3339 grant issue time")
	expiresAtText := flags.String("expires-at", "", "explicit UTC RFC3339 grant expiry time")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *deploymentID == "" || *cell == "" || *environment == "" || len(slots) == 0 ||
		*signerPublicPath == "" || *rootPublicPath == "" || *rootPrivatePath == "" || *outputPath == "" ||
		*issuedAtText == "" || *expiresAtText == "" || flags.NArg() != 0 {
		return errors.New("sign-ledger-delegation requires deployment, cell, environment, ordered slots, signer public key, root public/private keys, issue/expiry times, and output")
	}
	if *environment != "production" && *environment != "canary" ||
		!slices.IsSorted(slots) || len(slots) > bootstrap.MaxBootstrapAnchorSlots {
		return errors.New("ledger grant environment or ordered controller slots are invalid")
	}
	if _, err := oci.Region(*cell).OCIRegion(); err != nil {
		return err
	}
	issuedAt, err := time.Parse(time.RFC3339, *issuedAtText)
	if err != nil || issuedAt.Location() != time.UTC {
		return errors.New("ledger grant issued-at must be UTC RFC3339")
	}
	expiresAt, err := time.Parse(time.RFC3339, *expiresAtText)
	if err != nil || expiresAt.Location() != time.UTC || !expiresAt.After(issuedAt) ||
		expiresAt.Sub(issuedAt) > bootstrap.MaxBootstrapAnchorLifetime || now.Before(issuedAt) || !now.Before(expiresAt) {
		return errors.New("ledger grant must have a current UTC interval no longer than the anchor maximum")
	}
	rootPublic, err := readRootPublicKey(*rootPublicPath)
	if err != nil {
		return err
	}
	signerPublic, err := readRootPublicKey(*signerPublicPath)
	if err != nil {
		return err
	}
	if bytes.Equal(rootPublic, signerPublic) {
		return errors.New("delegated ledger signer must differ from the offline root")
	}
	rootPrivate, err := readRootPrivateKey(*rootPrivatePath)
	if err != nil {
		return err
	}
	defer clear(rootPrivate)
	if !bytes.Equal(rootPrivate.Public().(ed25519.PublicKey), rootPublic) {
		return errors.New("offline root signing key does not match the supplied root public key")
	}
	signerID, err := trust.KeyID(signerPublic)
	if err != nil {
		return err
	}
	signerWire, err := trust.EncodeDelegatedPublicKey(signerPublic)
	if err != nil {
		return err
	}
	domains := bootstrap.BootstrapLedgerCapabilityDomains()
	capabilities := make([]trust.Capability, 0, len(domains))
	for _, domain := range domains {
		capabilities = append(capabilities, trust.Capability{Domain: domain, DeploymentID: *deploymentID,
			Cell: *cell, Environment: *environment, Role: "controller", Slots: slices.Clone(slots), Actions: []string{"sign"}})
	}
	grant := trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: signerID,
		SubjectPublicKey: signerWire, Capabilities: capabilities}
	signed, err := trust.SignDelegation(grant, issuedAt, expiresAt, rootPrivate)
	if err != nil {
		return fmt.Errorf("sign exact ledger delegation: %w", err)
	}
	roots, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		return err
	}
	verified, err := trust.VerifyDelegationCurrent(signed, roots, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil || verified.SubjectKeyID() != signerID || !slices.EqualFunc(verified.Capabilities(), capabilities,
		func(a, b trust.Capability) bool {
			return a.Domain == b.Domain && a.DeploymentID == b.DeploymentID && a.Cell == b.Cell &&
				a.Environment == b.Environment && a.Role == b.Role && slices.Equal(a.Slots, b.Slots) &&
				slices.Equal(a.Actions, b.Actions)
		}) {
		return errors.New("signed ledger delegation failed exact-scope verification")
	}
	encoded, err := trust.EncodeEnvelope(signed)
	if err != nil {
		return err
	}
	if len(encoded) > bootstrap.MaxBootstrapLedgerGrantBytes {
		return errors.New("signed ledger delegation exceeds anchor size limit")
	}
	if err := c.writeNew(*outputPath, encoded, 0o644); err != nil {
		return err
	}
	fmt.Fprintf(c.output, "signed ledger delegation deployment=%s cell=%s signer=%s digest=%x expires=%s\n",
		*deploymentID, *cell, signerID, sha256.Sum256(encoded), expiresAt.Format(time.RFC3339))
	return nil
}

sign_anchor.text:
func (c command) signBootstrapAnchorAt(args []string, now time.Time) error {
	flags := flag.NewFlagSet("sign-anchor", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	candidatePath := flags.String("candidate", "", "reviewed unsigned deployment bootstrap anchor JSON")
	regionIntentPath := flags.String("region-intent", "", "canonical initial OCI region-intent JSON")
	ledgerDelegationPath := flags.String("ledger-delegation", "", "root-signed one-signer bootstrap ledger capability grant")
	rootPublicPath := flags.String("root-key", "", "offline root Ed25519 public key PEM")
	rootPrivatePath := flags.String("signing-key", "", "owner-only offline root Ed25519 PKCS#8 private key PEM")
	outputPath := flags.String("out", "", "new canonical signed anchor envelope")
	validFor := flags.Duration("valid-for", bootstrap.DefaultBootstrapAnchorValidity, "anchor validity, no longer than one year")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *candidatePath == "" || *regionIntentPath == "" || *ledgerDelegationPath == "" || *rootPublicPath == "" ||
		*rootPrivatePath == "" || *outputPath == "" || flags.NArg() != 0 {
		return errors.New("sign-anchor requires --candidate, --region-intent, --ledger-delegation, --root-key, --signing-key, and --out")
	}
	policy := bootstrap.BootstrapAnchorTrustPolicy()
	if *validFor <= 0 || *validFor > policy.MaxLifetime {
		return fmt.Errorf("anchor validity must be positive and no longer than %s", policy.MaxLifetime)
	}
	now = now.Round(0).UTC()
	if now.IsZero() {
		return errors.New("anchor signing time is invalid")
	}

	candidateBytes, err := c.readBoundedRegular(*candidatePath, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return err
	}
	var anchor bootstrap.BootstrapAnchor
	if err := protocol.DecodeStrict(candidateBytes, &anchor, bootstrap.MaxBootstrapAnchorBytes); err != nil {
		return fmt.Errorf("decode candidate anchor: %w", err)
	}
	regionIntentWire, err := c.readBoundedRegular(*regionIntentPath, bootstrap.MaxInitialRegionIntentBytes)
	if err != nil {
		return fmt.Errorf("read initial region intent: %w", err)
	}
	intent, err := oci.ParseRegionIntent(regionIntentWire)
	if err != nil {
		return fmt.Errorf("parse initial region intent: %w", err)
	}
	canonicalIntentWire, err := trust.EncodePayload(intent)
	if err != nil {
		return fmt.Errorf("encode canonical initial region intent: %w", err)
	}
	if !bytes.Equal(regionIntentWire, canonicalIntentWire) {
		return errors.New("initial region intent must be canonical JSON")
	}
	ledgerDelegationWire, err := c.readBoundedRegular(*ledgerDelegationPath, bootstrap.MaxBootstrapLedgerGrantBytes)
	if err != nil {
		return fmt.Errorf("read bootstrap ledger delegation: %w", err)
	}
	if len(anchor.LedgerDelegationWire) > 0 && !bytes.Equal(anchor.LedgerDelegationWire, ledgerDelegationWire) {
		return errors.New("candidate anchor contains a conflicting ledger delegation wire")
	}
	anchor.LedgerDelegationWire = bytes.Clone(ledgerDelegationWire)
	intentDigest := sha256.Sum256(regionIntentWire)
	intentDigestHex := hex.EncodeToString(intentDigest[:])
	if anchor.InitialRegionIntentGeneration != 0 && anchor.InitialRegionIntentGeneration != intent.Generation {
		return errors.New("candidate anchor contains a conflicting initial region-intent generation")
	}
	if anchor.InitialRegionIntentSHA256 != "" && anchor.InitialRegionIntentSHA256 != intentDigestHex {
		return errors.New("candidate anchor contains a conflicting initial region-intent digest")
	}
	if len(anchor.InitialRegionIntentWire) > 0 && !bytes.Equal(anchor.InitialRegionIntentWire, regionIntentWire) {
		return errors.New("candidate anchor contains conflicting initial region-intent bytes")
	}
	anchor.InitialRegionIntentGeneration = intent.Generation
	anchor.InitialRegionIntentSHA256 = intentDigestHex
	anchor.InitialRegionIntentWire = bytes.Clone(regionIntentWire)
	rootPublic, err := readRootPublicKey(*rootPublicPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		return fmt.Errorf("parse root trust key: %w", err)
	}
	ledgerDelegation, err := trust.DecodeEnvelope(ledgerDelegationWire)
	if err != nil {
		return fmt.Errorf("decode bootstrap ledger delegation: %w", err)
	}
	if _, err := trust.VerifyDelegationCurrent(ledgerDelegation, roots, now, policy); err != nil {
		return fmt.Errorf("verify current root-signed bootstrap ledger delegation: %w", err)
	}
	if err := anchor.Validate(); err != nil {
		return fmt.Errorf("validate candidate anchor: %w", err)
	}
	rootPrivate, err := readRootPrivateKey(*rootPrivatePath)
	if err != nil {
		return err
	}
	defer clear(rootPrivate)
	if !bytes.Equal(rootPrivate.Public().(ed25519.PublicKey), rootPublic) {
		return errors.New("offline root signing key does not match the supplied root public key")
	}
	issuedAt := now
	expiresAt := minTime(now.Add(*validFor), ledgerDelegation.ExpiresAt)
	if !expiresAt.After(issuedAt) {
		return errors.New("bootstrap ledger delegation leaves no anchor validity")
	}
	signed, err := bootstrap.SignBootstrapAnchor(anchor, issuedAt, expiresAt, rootPrivate)
	if err != nil {
		return fmt.Errorf("sign bootstrap anchor: %w", err)
	}
	expected := bootstrap.BootstrapAnchorExpectation{
		DeploymentID: anchor.DeploymentID, Environment: anchor.Environment, Cell: anchor.Cell,
	}
	verified, err := bootstrap.VerifyBootstrapAnchor(signed, roots, expected, now, policy)
	if err != nil {
		return fmt.Errorf("verify newly signed bootstrap anchor: %w", err)
	}
	if !bytes.Equal(verified.Anchor().InitialRegionIntentWire, regionIntentWire) ||
		verified.Anchor().InitialRegionIntentSHA256 != intentDigestHex || verified.Anchor().InitialRegionIntentGeneration != intent.Generation {
		return errors.New("signed anchor changed the canonical initial region-intent bytes")
	}
	encoded, err := trust.EncodeEnvelope(signed)
	if err != nil {
		return fmt.Errorf("encode signed bootstrap anchor: %w", err)
	}
	if len(encoded) > bootstrap.MaxBootstrapAnchorBytes {
		return fmt.Errorf("signed anchor envelope exceeds %d bytes", bootstrap.MaxBootstrapAnchorBytes)
	}
	if err := c.writeNew(*outputPath, encoded, 0o644); err != nil {
		return err
	}
	fmt.Fprintf(c.output, "signed bootstrap anchor cell=%s cluster=%s digest=%s expires=%s\n",
		anchor.Cell, anchor.ClusterID, verified.Digest(), verified.ExpiresAt().Format(time.RFC3339))
	return nil
}

sign_manifest.text:
func (c command) signManifestAt(args []string, now time.Time) error {
	flags := flag.NewFlagSet("sign-manifest", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	candidatePath := flags.String("candidate", "", "reviewed unsigned bootstrap manifest JSON")
	controllerConfigPath := flags.String("controller-config", "", "reviewed canonical controller role JSON")
	controllerConfigSHA := flags.String("controller-config-sha256", "", "reviewed controller role SHA-256")
	regionIntentPath := flags.String("oci-region-intent", "", "reviewed canonical regional intent JSON")
	regionIntentSHA := flags.String("oci-region-intent-sha256", "", "reviewed regional intent SHA-256")
	regionConfigPath := flags.String("oci-region-config", "", "reviewed canonical regional fleet JSON")
	regionConfigSHA := flags.String("oci-region-config-sha256", "", "reviewed regional fleet SHA-256")
	placementPath := flags.String("placement-config", "", "reviewed canonical placement JSON")
	placementSHA := flags.String("placement-config-sha256", "", "reviewed placement SHA-256")
	anchorPath := flags.String("anchor", "", "current root-signed deployment bootstrap anchor envelope")
	imageReceiptPath := flags.String("image-receipt", "", "canonical signed OCI image receipt envelope")
	releaseDelegationPath := flags.String("release-delegation", "", "canonical root-signed release delegation envelope")
	rootPublicPath := flags.String("root-key", "", "offline root Ed25519 public key PEM")
	rootPrivatePath := flags.String("signing-key", "", "owner-only offline root Ed25519 PKCS#8 private key PEM")
	outputPath := flags.String("out", "", "new canonical signed manifest envelope")
	validFor := flags.Duration("valid-for", bootstrap.DefaultManifestValidity, "manifest validity, bounded by current proof expiries")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *candidatePath == "" || *controllerConfigPath == "" || *controllerConfigSHA == "" ||
		*regionIntentPath == "" || *regionIntentSHA == "" || *regionConfigPath == "" ||
		*regionConfigSHA == "" || *placementPath == "" || *placementSHA == "" ||
		*anchorPath == "" || *imageReceiptPath == "" || *releaseDelegationPath == "" ||
		*rootPublicPath == "" || *rootPrivatePath == "" || *outputPath == "" || flags.NArg() != 0 {
		return errors.New("sign-manifest requires the reviewed controller config and three sidecars with SHA-256 pins, candidate, anchor, release proofs, root keys, and output")
	}
	policy := bootstrap.ManifestTrustPolicy()
	if *validFor <= 0 || *validFor > policy.MaxLifetime {
		return fmt.Errorf("manifest validity must be positive and no longer than %s", policy.MaxLifetime)
	}
	now = now.Round(0).UTC()
	if now.IsZero() {
		return errors.New("manifest signing time is invalid")
	}

	candidateBytes, err := c.readBoundedRegular(*candidatePath, bootstrap.MaxManifestBytes)
	if err != nil {
		return err
	}
	var manifest bootstrap.Manifest
	if err := protocol.DecodeStrict(candidateBytes, &manifest, bootstrap.MaxManifestBytes); err != nil {
		return fmt.Errorf("decode candidate manifest: %w", err)
	}
	if err := attachReviewedControllerConfig(&manifest, *controllerConfigPath, *controllerConfigSHA,
		*regionIntentPath, *regionIntentSHA, *regionConfigPath, *regionConfigSHA,
		*placementPath, *placementSHA); err != nil {
		return err
	}
	imageWire, err := c.readBoundedRegular(*imageReceiptPath, bootstrap.MaxManifestBytes)
	if err != nil {
		return fmt.Errorf("read image receipt: %w", err)
	}
	delegationWire, err := c.readBoundedRegular(*releaseDelegationPath, bootstrap.MaxManifestBytes)
	if err != nil {
		return fmt.Errorf("read release delegation: %w", err)
	}
	if len(manifest.ReleaseImageReceiptWire) > 0 && !bytes.Equal(manifest.ReleaseImageReceiptWire, imageWire) {
		return errors.New("candidate manifest contains a conflicting image receipt wire")
	}
	if len(manifest.ReleaseDelegationWire) > 0 && !bytes.Equal(manifest.ReleaseDelegationWire, delegationWire) {
		return errors.New("candidate manifest contains a conflicting release delegation wire")
	}
	imageDigest := sha256.Sum256(imageWire)
	imageDigestHex := hex.EncodeToString(imageDigest[:])
	if manifest.ReleaseReceiptSHA256 != imageDigestHex {
		return errors.New("candidate release receipt SHA-256 does not match the exact supplied image envelope wire")
	}
	rootPublic, err := readRootPublicKey(*rootPublicPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		return fmt.Errorf("parse root trust key: %w", err)
	}
	rootPrivate, err := readRootPrivateKey(*rootPrivatePath)
	if err != nil {
		return err
	}
	defer clear(rootPrivate)
	if !bytes.Equal(rootPrivate.Public().(ed25519.PublicKey), rootPublic) {
		return errors.New("offline root signing key does not match the supplied root public key")
	}
	anchorWire, err := c.readBoundedRegular(*anchorPath, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return fmt.Errorf("read bootstrap anchor: %w", err)
	}
	anchorEnvelope, err := trust.DecodeEnvelope(anchorWire)
	if err != nil {
		return fmt.Errorf("decode bootstrap anchor: %w", err)
	}
	verifiedAnchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, roots, bootstrap.BootstrapAnchorExpectation{
		DeploymentID: manifest.DeploymentID, Environment: manifest.Environment, Cell: manifest.Cell,
	}, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return fmt.Errorf("verify current bootstrap anchor: %w", err)
	}
	expected, err := verifiedAnchor.ManifestExpectation(manifest.Slot, manifest.ImageOCID)
	if err != nil {
		return fmt.Errorf("derive bootstrap manifest expectation from anchor: %w", err)
	}
	if manifest.ClusterID != expected.ClusterID || manifest.StorageDomain != expected.StorageDomain ||
		!equalOrderedStrings(manifest.ControllerSlots, expected.ControllerSlots) ||
		manifest.IntentGeneration != expected.IntentGeneration || manifest.IntentSHA256 != expected.IntentSHA256 {
		return errors.New("candidate manifest identity, storage domain, controller slots, or region-intent pin does not match the signed anchor")
	}
	architecture, err := releaseArchitecture(manifest.ImageArchitecture)
	if err != nil {
		return err
	}
	imageProof, err := release.VerifyImageCurrent(imageWire, delegationWire, roots, release.ImageExpectation{
		Environment: manifest.Environment, LogicalRegion: string(manifest.Cell),
		OCIImageOCID: manifest.ImageOCID, Architecture: architecture,
	}, now)
	if err != nil {
		return fmt.Errorf("verify current release image proof: %w", err)
	}
	if imageProof.EnvelopeSHA256() != imageDigestHex {
		return errors.New("verified image receipt digest differs from the exact supplied wire")
	}
	delegationEnvelope, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return fmt.Errorf("decode release delegation: %w", err)
	}
	manifest.ReleaseImageReceiptWire = bytes.Clone(imageWire)
	manifest.ReleaseDelegationWire = bytes.Clone(delegationWire)
	if err := manifest.Validate(); err != nil {
		return fmt.Errorf("validate candidate manifest: %w", err)
	}

	issuedAt := now
	expiresAt := now.Add(*validFor)
	expiresAt = minTime(minTime(minTime(expiresAt, imageProof.ExpiresAt()), delegationEnvelope.ExpiresAt), verifiedAnchor.ExpiresAt())
	if manifest.PeerReceiptDelegation != nil {
		expiresAt = minTime(expiresAt, manifest.PeerReceiptDelegation.ExpiresAt)
	}
	if expiresAt.Sub(issuedAt) < bootstrap.MinimumManifestWindow {
		return fmt.Errorf("current release or peer proof leaves less than %s of manifest validity", bootstrap.MinimumManifestWindow)
	}
	signed, err := bootstrap.SignManifest(manifest, issuedAt, expiresAt, rootPrivate)
	if err != nil {
		return fmt.Errorf("sign bootstrap manifest: %w", err)
	}
	verified, err := bootstrap.VerifyManifest(signed, roots, expected, now, policy)
	if err != nil {
		return fmt.Errorf("verify newly signed bootstrap manifest: %w", err)
	}
	verifiedManifest := verified.Manifest()
	if !bytes.Equal(verifiedManifest.ReleaseImageReceiptWire, imageWire) ||
		!bytes.Equal(verifiedManifest.ReleaseDelegationWire, delegationWire) || verifiedManifest.ReleaseReceiptSHA256 != imageDigestHex {
		return errors.New("signed manifest changed the verified release proof bytes")
	}
	encoded, err := trust.EncodeEnvelope(signed)
	if err != nil {
		return fmt.Errorf("encode signed manifest: %w", err)
	}
	if len(encoded) > bootstrapstart.MaxControllerManifestMetadataBytes {
		return fmt.Errorf("signed manifest envelope exceeds %d-byte OCI metadata transport", bootstrapstart.MaxControllerManifestMetadataBytes)
	}
	if err := c.writeNew(*outputPath, encoded, 0o644); err != nil {
		return err
	}
	fmt.Fprintf(c.output, "signed current bootstrap manifest cell=%s slot=%s digest=%s expires=%s\n",
		manifest.Cell, manifest.Slot, verified.Digest(), expiresAt.Format(time.RFC3339))
	return nil
}

public_key.text:
func readRootPublicKey(path string) (ed25519.PublicKey, error) {
	data, err := readBoundedRegular(path, maxKeyFileBytes)
	if err != nil {
		return nil, err
	}
	return parseRootPublicKey(data)
}

func parseRootPublicKey(data []byte) (ed25519.PublicKey, error) {
	block, rest := pem.Decode(data)
	if block == nil || block.Type != "PUBLIC KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("root public key must be a PEM Ed25519 SubjectPublicKeyInfo")
	}
	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse root public key: %w", err)
	}
	public, ok := parsed.(ed25519.PublicKey)
	if !ok || len(public) != ed25519.PublicKeySize {
		return nil, errors.New("root public key must be Ed25519")
	}
	return public, nil
}

private_key.text:
func readRootPrivateKey(path string) (ed25519.PrivateKey, error) {
	file, err := openRegular(path)
	if err != nil {
		return nil, fmt.Errorf("open offline root signing key: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat offline root signing key: %w", err)
	}
	if info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("offline root signing key must be an owner-only file")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("offline root signing key must be owned by this process user")
	}
	if info.Size() <= 0 || info.Size() > maxKeyFileBytes {
		return nil, fmt.Errorf("offline root signing key exceeds %d bytes", maxKeyFileBytes)
	}
	data, err := io.ReadAll(io.LimitReader(file, maxKeyFileBytes+1))
	if err != nil {
		return nil, fmt.Errorf("read offline root signing key: %w", err)
	}
	block, rest := pem.Decode(data)
	if block == nil || block.Type != "PRIVATE KEY" || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("offline root signing key must be PEM PKCS#8 Ed25519")
	}
	parsed, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse offline root signing key: %w", err)
	}
	private, ok := parsed.(ed25519.PrivateKey)
	if !ok || len(private) != ed25519.PrivateKeySize {
		return nil, errors.New("offline root signing key must be Ed25519")
	}
	return private, nil
}

file_read.text:
func readBoundedRegular(path string, maximum int64) ([]byte, error) {
	return readBoundedRegularContext(context.Background(), path, maximum)
}

func (c command) readBoundedRegular(path string, maximum int64) ([]byte, error) {
	return readBoundedRegularContext(c.ctx, path, maximum)
}

func readBoundedRegularContext(ctx context.Context, path string, maximum int64) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	file, err := openRegular(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat %s: %w", filepath.Base(path), err)
	}
	if info.Size() < 0 || info.Size() > maximum {
		return nil, fmt.Errorf("%s exceeds the %d-byte limit", filepath.Base(path), maximum)
	}
	data, err := io.ReadAll(io.LimitReader(commandio.Reader(ctx, file), maximum+1))
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", filepath.Base(path), err)
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%s exceeds the %d-byte limit", filepath.Base(path), maximum)
	}
	return data, nil
}

func openRegular(path string) (*os.File, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, fmt.Errorf("stat %s: %w", filepath.Base(path), err)
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%s must be a regular file", filepath.Base(path))
	}
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", filepath.Base(path), err)
	}
	opened, err := file.Stat()
	if err != nil || !os.SameFile(info, opened) {
		_ = file.Close()
		return nil, fmt.Errorf("%s changed while opening", filepath.Base(path))
	}
	return file, nil
}

write_new.text:
func (c command) writeNew(path string, contents []byte, mode os.FileMode) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if path == "" || len(contents) == 0 {
		return errors.New("output path and content are required")
	}
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return fmt.Errorf("create output without overwrite: %w", err)
	}
	if err := c.ctx.Err(); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return err
	}
	if _, err := file.Write(contents); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return err
	}
	if err := file.Close(); err != nil {
		_ = os.Remove(path)
		return err
	}
	if err := c.ctx.Err(); err != nil {
		_ = os.Remove(path)
		return err
	}
	return nil
}

attach_config.text:
func attachReviewedControllerConfig(manifest *bootstrap.Manifest, configPath, configSHA,
	intentPath, intentSHA, regionPath, regionSHA, placementPath, placementSHA string,
) error {
	if manifest == nil {
		return errors.New("controller manifest is absent")
	}
	configWire, err := readPinnedControllerFile(configPath, configSHA, bootstrap.MaxControllerConfigBytes)
	if err != nil {
		return fmt.Errorf("reviewed controller config: %w", err)
	}
	files := make([]bootstrap.ControllerConfigFile, 0, len(bootstrap.ControllerConfigFileNames))
	for index, source := range []struct{ path, digest string }{
		{intentPath, intentSHA}, {regionPath, regionSHA}, {placementPath, placementSHA},
	} {
		wire, err := readPinnedControllerFile(source.path, source.digest, bootstrap.MaxControllerSidecarBytes)
		if err != nil {
			return fmt.Errorf("reviewed %s: %w", bootstrap.ControllerConfigFileNames[index], err)
		}
		files = append(files, bootstrap.ControllerConfigFile{
			Name: bootstrap.ControllerConfigFileNames[index], SHA256: source.digest, Bytes: wire,
		})
	}
	if len(manifest.ControllerConfig) != 0 && !bytes.Equal(manifest.ControllerConfig, configWire) ||
		manifest.ControllerConfigSHA256 != "" && manifest.ControllerConfigSHA256 != configSHA ||
		len(manifest.ControllerFiles) != 0 && !sameControllerFiles(manifest.ControllerFiles, files) {
		return errors.New("candidate controller config conflicts with reviewed exact bytes")
	}
	manifest.ControllerConfig = configWire
	manifest.ControllerConfigSHA256 = configSHA
	manifest.ControllerFiles = files
	_, err = app.ValidateSignedControllerConfig(*manifest, "")
	return err
}

func readPinnedControllerFile(path, digest string, maximum int) ([]byte, error) {
	if path == "" || !filepath.IsAbs(path) || len(digest) != 64 {
		return nil, errors.New("absolute path and lowercase SHA-256 are required")
	}
	wire, err := readBoundedRegular(path, int64(maximum))
	if err != nil {
		return nil, err
	}
	if len(wire) == 0 || !matchesSHA256(wire, digest) {
		return nil, errors.New("exact reviewed SHA-256 does not match")
	}
	return wire, nil
}

func sameControllerFiles(left, right []bootstrap.ControllerConfigFile) bool {
	if len(left) != len(right) {
		return false
	}
	for index := range left {
		if left[index].Name != right[index].Name || left[index].SHA256 != right[index].SHA256 ||
			!bytes.Equal(left[index].Bytes, right[index].Bytes) {
			return false
		}
	}
	return true
}

signed_config.text:
func ValidateSignedControllerConfig(manifest bootstrap.Manifest, observedPrivateIP string) (Config, error) {
	cfg, err := ValidateInstalledControllerConfig(manifest, observedPrivateIP)
	if err != nil {
		return Config{}, err
	}
	canonical, err := protocol.EncodeJSON(cfg)
	if err != nil || !bytes.Equal(canonical, manifest.ControllerConfig) {
		return Config{}, errors.New("signed controller config must be canonical app.Config JSON")
	}
	return cfg, nil
}

// ValidateLoadedControllerConfig is ValidateInstalledControllerConfig for the
// loaded config, whose digest must be want: the config an adopted material
// generation pins for the slot (TS-668), or else the manifest's own.
func ValidateLoadedControllerConfig(manifest bootstrap.Manifest, config []byte, want, observedPrivateIP string,
) (Config, error) {
	manifest.ControllerConfig, manifest.ControllerConfigSHA256 = config, want
	return ValidateInstalledControllerConfig(manifest, observedPrivateIP)
}

// ValidateInstalledControllerConfig checks the role-specific meaning of the
// exact signed bytes. Guest installation and every restart re-check configs
// against the current schema, so the digest covers the bytes, not a
// re-encoding. observedPrivateIP is empty during offline signing and is the
// independently observed primary VNIC address on the guest.
func ValidateInstalledControllerConfig(manifest bootstrap.Manifest, observedPrivateIP string) (Config, error) {
	return validateControllerConfig(controllerConfigBinding{
		DeploymentID: manifest.DeploymentID, Cell: manifest.Cell, Slot: manifest.Slot,
		SeedSlot: manifest.SeedSlot, Environment: manifest.Environment, ControllerSlots: manifest.ControllerSlots,
		ControllerConfig: manifest.ControllerConfig, ControllerConfigSHA256: manifest.ControllerConfigSHA256,
		ControllerFiles: manifest.ControllerFiles, Secrets: manifest.Secrets,
		IntentGeneration: manifest.IntentGeneration, IntentSHA256: manifest.IntentSHA256,
	}, observedPrivateIP)
}

type controllerConfigBinding struct {
	DeploymentID, Slot, SeedSlot, Environment string
	Cell                                      oci.Region
	ControllerSlots                           []string
	ControllerConfig                          []byte
	ControllerConfigSHA256                    string
	ControllerFiles                           []bootstrap.ControllerConfigFile
	Secrets                                   []bootstrap.SecretReference
	IntentGeneration                          uint64
	IntentSHA256                              string
}

validate_config.text:
func validateControllerConfig(manifest controllerConfigBinding, observedPrivateIP string) (Config, error) {
	if len(manifest.ControllerConfig) > bootstrap.MaxControllerConfigBytes ||
		controllerSHA256(manifest.ControllerConfig) != manifest.ControllerConfigSHA256 {
		return Config{}, errors.New("signed controller config differs from its signed digest")
	}
	cfg, err := decodeConfig(manifest.ControllerConfig)
	if err != nil {
		return Config{}, fmt.Errorf("decode signed controller config: %w", err)
	}
	hostConfig := cfg.Host
	if len(hostConfig.Roles) == 0 {
		hostConfig.Roles = nil
	}
	if cfg.NATS.Cell != strings.ToLower(string(manifest.Cell)) || cfg.NATS.Instance != manifest.Slot ||
		cfg.NATS.Replicas != len(manifest.ControllerSlots) || cfg.NATS.Embedded == nil ||
		cfg.Controller.CandidateID != entityid.Derive("controller", manifest.DeploymentID, string(manifest.Cell), manifest.Slot) ||
		!reflect.DeepEqual(hostConfig, HostConfig{}) ||
		cfg.Operator != (OperatorConfig{}) ||
		cfg.Controller.OciRegionConfig != controllerSidecarPath("oci-region.json") ||
		cfg.Controller.OciRegionIntentFile != controllerSidecarPath("oci-region-intent.json") ||
		cfg.Controller.PlacementConfig != controllerSidecarPath("placement.json") ||
		cfg.NATS.NKeySeedFile != "" || cfg.Controller.TrustKeyFile != "" || cfg.Controller.SpecTrust != nil {
		return Config{}, errors.New("signed controller config does not match role, slot, or fixed paths")
	}
	if observedPrivateIP != "" && (cfg.NATS.Embedded.Host != observedPrivateIP ||
		cfg.NATS.Embedded.RouteHost != observedPrivateIP) {
		return Config{}, errors.New("signed broker addresses differ from the observed primary VNIC")
	}
	address, addressErr := netip.ParseAddr(cfg.NATS.Embedded.Host)
	if addressErr != nil || !address.Is4() || !address.IsPrivate() || address.String() != cfg.NATS.Embedded.Host ||
		cfg.NATS.Embedded.RouteHost != cfg.NATS.Embedded.Host || cfg.NATS.Embedded.Port != 4222 ||
		cfg.NATS.Embedded.RoutePort != 6222 || cfg.NATS.URL != "tls://"+cfg.NATS.Embedded.Host+":4222" ||
		cfg.NATS.Embedded.StoreDir != "/var/lib/terrascale-orchestrator-controller/nats" ||
		cfg.NATS.Embedded.StoreMaxBytes < 2<<30 || cfg.NATS.Embedded.StoreMaxBytes > 8<<30 ||
		cfg.NATS.Embedded.RouteUser != "ts-route" || len(cfg.NATS.Embedded.Users) != 0 ||
		!slices.Equal(cfg.NATS.Embedded.BrokerIDs, manifest.ControllerSlots) ||
		len(cfg.NATS.Embedded.Routes) != len(manifest.ControllerSlots)-1 {
		return Config{}, errors.New("signed controller broker runtime is outside the reviewed shape")
	}
	seenRoutes := make(map[string]bool, len(cfg.NATS.Embedded.Routes))
	for _, route := range cfg.NATS.Embedded.Routes {
		if !strings.HasPrefix(route, "nats-route://") || !strings.HasSuffix(route, ":6222") ||
			seenRoutes[route] || route == "nats-route://"+cfg.NATS.Embedded.Host+":6222" {
			return Config{}, errors.New("signed controller route is invalid or duplicated")
		}
		peer, err := netip.ParseAddr(strings.TrimSuffix(strings.TrimPrefix(route, "nats-route://"), ":6222"))
		if err != nil || !peer.Is4() || !peer.IsPrivate() {
			return Config{}, errors.New("signed controller route address is invalid")
		}
		seenRoutes[route] = true
	}
	if cfg.Controller.HostEnrollmentListenAddress != cfg.NATS.Embedded.Host+":8443" {
		return Config{}, errors.New("host enrollment listener differs from the signed controller address")
	}
	if err := validateSignedObservability(cfg); err != nil {
		return Config{}, err
	}
	// The Machines API has no signed listener, TLS material or load balancer
	// yet (docs/machines-api.md, slice 7); until it does, a production
	// controller must not try to bind it.
	if cfg.Controller.MachinesAPI != nil {
		return Config{}, errors.New("signed controller config may not enable machines_api yet")
	}
	if _, err := buildSignerPolicy(cfg); err != nil {
		return Config{}, fmt.Errorf("signed controller operator grant: %w", err)
	}
	if len(manifest.ControllerFiles) != len(bootstrap.ControllerConfigFileNames) {
		return Config{}, errors.New("signed controller sidecars are incomplete")
	}
	for index, file := range manifest.ControllerFiles {
		if file.Name != bootstrap.ControllerConfigFileNames[index] ||
			controllerSHA256(file.Bytes) != file.SHA256 {
			return Config{}, errors.New("signed controller sidecar digest or name is invalid")
		}
	}
	secretFiles := make(map[string]struct{}, len(manifest.Secrets))
	for _, reference := range manifest.Secrets {
		if reference.Purpose == bootstrap.SecretRegionalShared ||
			reference.Purpose == bootstrap.SecretHostIssuer ||
			reference.Purpose == bootstrap.SecretController && reference.Slot == manifest.Slot ||
			(reference.Purpose == bootstrap.SecretSeedFounder || reference.Purpose == bootstrap.SecretSeedLedgerSigner) &&
				manifest.Slot == manifest.SeedSlot {
			secretFiles[reference.TargetFile] = struct{}{}
		}
	}
	paths := []string{cfg.NATS.CredentialsFile, cfg.NATS.TLS.CAFile, cfg.NATS.TLS.CertFile,
		cfg.NATS.TLS.KeyFile, cfg.NATS.Embedded.TLS.CAFile, cfg.NATS.Embedded.TLS.CertFile,
		cfg.NATS.Embedded.TLS.KeyFile, cfg.NATS.Embedded.RouteTLS.CAFile,
		cfg.NATS.Embedded.RouteTLS.CertFile, cfg.NATS.Embedded.RouteTLS.KeyFile,
		cfg.NATS.Embedded.RoutePasswordFile, cfg.NATS.Embedded.OperatorJWTFile,
		cfg.NATS.Embedded.SystemJWTFile, cfg.NATS.Embedded.CellJWTFile,
		cfg.NATS.Embedded.SystemCredentialsFile, cfg.NATS.Embedded.TicketPublicKeyFile,
		cfg.Controller.ResponseKeyFile, cfg.Controller.BrokerTicketKeyFile,
		cfg.Controller.HostNATSIssuerSeedFile, cfg.Controller.HostTLSIssuerKeyFile,
		cfg.Controller.HostTLSIssuerCertFile}
	for _, path := range paths {
		name := filepath.Base(path)
		if path == "" || path != filepath.Join(bootstrapstart.MaterialDirectory, name) {
			return Config{}, errors.New("controller credential path escapes the signed material directory")
		}
		if _, exists := secretFiles[name]; !exists {
			return Config{}, fmt.Errorf("controller credential %s is absent from signed material", name)
		}
	}
	// Interregion and link files come from an adopted material generation, whose
	// pins restart admission checks (TS-668); they too live in the directory.
	for _, path := range append(cfg.NATS.Embedded.InterRegion.Files(), cfg.NATS.Embedded.Link.Files()...) {
		if path != filepath.Join(bootstrapstart.MaterialDirectory, filepath.Base(path)) {
			return Config{}, errors.New("interregion or link credential path escapes the signed material directory")
		}
	}
	// The C# TerraBase member CA is host-issuer material: configured exactly
	// when signed, at its fixed paths, as the live credential check requires.
	_, signedCACert := secretFiles["terrabase-member-ca.pem"]
	_, signedCAKey := secretFiles["terrabase-member-ca.key"]
	if cfg.Controller.TerraBaseCACertFile != "" || cfg.Controller.TerraBaseCAKeyFile != "" || signedCACert || signedCAKey {
		if !signedCACert || !signedCAKey ||
			cfg.Controller.TerraBaseCACertFile != filepath.Join(bootstrapstart.MaterialDirectory, "terrabase-member-ca.pem") ||
			cfg.Controller.TerraBaseCAKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, "terrabase-member-ca.key") {
			return Config{}, errors.New("TerraBase member CA is not the signed slot material")
		}
	}
	// Without the member CA no member gets a certificate or starts.
	if _, terraBase := cfg.Controller.Workloads[terrabase.Role]; terraBase && !signedCACert {
		return Config{}, errors.New("a signed TerraBase workload profile needs the signed member CA")
	}
	if err := validateWorkloadProfiles(cfg.NATS.Cell, cfg.Controller.Workloads); err != nil {
		return Config{}, fmt.Errorf("signed controller workloads: %w", err)
	}
	if err := validateAutoscaleConfig(cfg.Controller.Autoscale, cfg.Controller.Workloads); err != nil {
		return Config{}, fmt.Errorf("signed controller autoscale: %w", err)
	}
	if path := cfg.NATS.Embedded.MembershipCredentialsFile; path != "" {
		if _, signed := secretFiles["membership.creds"]; !signed ||
			path != filepath.Join(bootstrapstart.MaterialDirectory, "membership.creds") {
			return Config{}, errors.New("membership credentials are not the signed slot material")
		}
	}
	if cfg.Controller.ResponseKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, manifest.Slot+"-response.key") ||
		cfg.Controller.BrokerTicketKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, "ticket.key") ||
		cfg.Controller.HostNATSIssuerSeedFile != filepath.Join(bootstrapstart.MaterialDirectory, "host-nats-issuer.seed") ||
		cfg.Controller.HostTLSIssuerKeyFile != filepath.Join(bootstrapstart.MaterialDirectory, "host-tls-issuer-key.pem") ||
		cfg.Controller.HostTLSIssuerCertFile != filepath.Join(bootstrapstart.MaterialDirectory, "host-tls-issuer-cert.pem") {
		return Config{}, errors.New("controller response or broker-ticket key does not match the slot")
	}
	intent, err := oci.ParseRegionIntent(manifest.ControllerFiles[0].Bytes)
	if err != nil || intent.Generation != manifest.IntentGeneration ||
		manifest.ControllerFiles[0].SHA256 != manifest.IntentSHA256 {
		return Config{}, errors.New("controller regional intent differs from signed anchor pin")
	}
	region, err := oci.ParseRegionConfig(manifest.ControllerFiles[1].Bytes)
	if err != nil || region.Validate(intent) != nil || region.Region != manifest.Cell {
		return Config{}, errors.New("controller fleet config differs from signed region")
	}
	var placement managedPlacementSettings
	if err := protocol.DecodeStrict(manifest.ControllerFiles[2].Bytes, &placement, bootstrap.MaxControllerSidecarBytes); err != nil ||
		placement.Environment != manifest.Environment || placement.MemberRole == "" {
		return Config{}, errors.New("controller placement config differs from signed environment")
	}
	// Controller start refuses the same overlap; refuse it before signing.
	if _, exists := cfg.Controller.Workloads[placement.MemberRole]; exists {
		return Config{}, fmt.Errorf("placement member role %q overlaps a generic delivery workload profile", placement.MemberRole)
	}
	return cfg, nil
}

// validateSignedObservability keeps a signed controller's telemetry listener
// on loopback or on its own signed private broker address, never on another
// interface, and keeps any token or TLS file under the signed config root.
func validateSignedObservability(cfg Config) error {
	settings := cfg.Observability
	if err := settings.Validate(); err != nil {
		return fmt.Errorf("signed controller observability: %w", err)
	}
	address, err := netip.ParseAddrPort(settings.Address())
	if err != nil || !address.Addr().IsLoopback() && address.Addr().String() != cfg.NATS.Embedded.Host {
		return errors.New("signed observability listener must bind loopback or the signed broker address")
	}
	for _, path := range []string{settings.BearerTokenFile, settings.TLSCertFile, settings.TLSKeyFile} {
		if path != "" && (filepath.Clean(path) != path ||
			!strings.HasPrefix(path, controllerConfigDirectory+"/")) {
			return errors.New("signed observability files must live under the controller config directory")
		}
	}
	return nil
}

func controllerSidecarPath(name string) string {
	return filepath.Join(controllerConfigDirectory, name)
}

func controllerSHA256(wire []byte) string {
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

decode_config.text:
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

signer_policy.text:
func buildSignerPolicy(cfg Config) (signerPolicy, error) {
	set, err := newSignerSet(cfg.Controller.TrustedSigners)
	if err != nil {
		return signerPolicy{}, err
	}
	signers := &atomic.Pointer[signerSet]{}
	signers.Store(&set)
	releases := &atomic.Pointer[delegatedReleaseSigner]{}
	return signerPolicy{
		codec: delivery.Ed25519Codec{Cell: cfg.NATS.Cell, Lifetime: time.Minute, MaxLifetime: 5 * time.Minute,
			ClockSkew: 30 * time.Second, Lookup: func(keyID string) (delivery.TrustedSigner, bool) {
				if trusted, ok := signers.Load().trusted[keyID]; ok {
					return trusted, true
				}
				if delegated := releases.Load(); delegated.current() && delegated.keyID == keyID {
					return delivery.TrustedSigner{Actor: delegated.actor, PublicKey: delegated.key}, true
				}
				return delivery.TrustedSigner{}, false
			}},
		signers: signers, release: releases, cell: cfg.NATS.Cell,
	}, nil
}

json.text:
// EncodeJSON emits deterministic JSON. Deterministic map ordering keeps a given Go
// value's wire representation stable; signed payloads are also compacted before
// their digest is calculated.
func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

keyring.text:
func ParseKeyring(publicKeys ...ed25519.PublicKey) (Keyring, error) {
	keyring := make(Keyring, len(publicKeys))
	for _, publicKey := range publicKeys {
		keyID, err := KeyID(publicKey)
		if err != nil {
			return nil, err
		}
		if _, exists := keyring[keyID]; exists {
			return nil, fmt.Errorf("%w: duplicate trusted root", ErrInvalid)
		}
		keyring[keyID] = append(ed25519.PublicKey(nil), publicKey...)
	}
	if len(keyring) == 0 {
		return nil, fmt.Errorf("%w: empty trusted root set", ErrInvalid)
	}
	return keyring, nil
}

anchor_validate.text:
func (anchor BootstrapAnchor) Validate() error {
	ociRegion, err := anchor.Cell.OCIRegion()
	if err != nil || anchor.SchemaVersion != BootstrapAnchorSchemaVersion ||
		!entityid.Valid(anchor.DeploymentID) || !entityid.Valid(anchor.ClusterID) ||
		(anchor.Environment != "production" && anchor.Environment != "canary") || anchor.OCIRegion != ociRegion {
		return fmt.Errorf("%w: required identity or region binding", ErrBootstrapAnchorInvalid)
	}
	if anchor.FoundationScope != nil {
		if err := anchor.FoundationScope.Validate(); err != nil {
			return err
		}
		if anchor.Cell == "GRU" && (anchor.FoundationScope.DeploymentID != anchor.DeploymentID || anchor.FoundationScope.ClusterID != anchor.ClusterID || anchor.FoundationScope.StorageDomain != anchor.StorageDomain) {
			return fmt.Errorf("%w: home discovery identity differs from home anchor", ErrBootstrapAnchorInvalid)
		}
	}
	if err := anchor.StorageDomain.Validate(); err != nil {
		return fmt.Errorf("%w: %v", ErrBootstrapAnchorInvalid, err)
	}
	if len(anchor.ControllerSlots) == 0 || len(anchor.ControllerSlots) > MaxBootstrapAnchorSlots ||
		hasDuplicate(anchor.ControllerSlots) || !slices.IsSorted(anchor.ControllerSlots) {
		return fmt.Errorf("%w: controller slot set is absent, oversized, duplicated, or not sorted", ErrBootstrapAnchorInvalid)
	}
	for _, slot := range anchor.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return fmt.Errorf("%w: invalid controller slot %q", ErrBootstrapAnchorInvalid, slot)
		}
	}
	if anchor.InitialSourceRegistration != nil {
		registration := anchor.InitialSourceRegistration
		if len(anchor.LedgerDelegationWire) != 0 || anchor.FoundationScope == nil || registration.Validate() != nil || registration.DeploymentID != anchor.DeploymentID || registration.Environment != anchor.Environment || registration.ClusterID != anchor.ClusterID || registration.Cell != anchor.Cell || registration.Generation != anchor.FoundationScope.GrantGeneration || registration.InstallationID != anchor.FoundationScope.InstallationID || registration.StorageDomain != anchor.StorageDomain || !slices.Equal(registration.ControllerSlots, anchor.ControllerSlots) {
			return fmt.Errorf("%w: source registration differs from exact anchor or replaces pinned ledger signer", ErrBootstrapAnchorInvalid)
		}
	} else {
		if len(anchor.LedgerDelegationWire) == 0 || len(anchor.LedgerDelegationWire) > MaxBootstrapLedgerGrantBytes {
			return fmt.Errorf("%w: ledger delegation wire is absent or exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapLedgerGrantBytes)
		}
		grantEnvelope, err := trust.DecodeEnvelope(anchor.LedgerDelegationWire)
		if err != nil {
			return fmt.Errorf("%w: decode ledger delegation wire: %v", ErrBootstrapAnchorInvalid, err)
		}
		grant, err := decodeBootstrapLedgerDelegation(grantEnvelope)
		if err != nil {
			return err
		}
		if err := validateBootstrapLedgerCapabilities(grant, anchor); err != nil {
			return err
		}
	}
	if len(anchor.InitialRegionIntentWire) == 0 || len(anchor.InitialRegionIntentWire) > MaxInitialRegionIntentBytes ||
		anchor.InitialRegionIntentGeneration == 0 || !sha256RE.MatchString(anchor.InitialRegionIntentSHA256) {
		return fmt.Errorf("%w: initial region intent is absent or exceeds its size bound", ErrBootstrapAnchorInvalid)
	}
	intent, err := canonicalRegionIntent(anchor.InitialRegionIntentWire)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrBootstrapAnchorInvalid, err)
	}
	if intent.Generation != anchor.InitialRegionIntentGeneration || digestBytes(anchor.InitialRegionIntentWire) != anchor.InitialRegionIntentSHA256 {
		return fmt.Errorf("%w: initial region-intent generation or exact-wire digest does not match", ErrBootstrapAnchorInvalid)
	}
	if !slices.ContainsFunc(intent.Regions, func(mapping oci.RegionMapping) bool {
		return mapping.Cell == anchor.Cell && mapping.OCIRegion == anchor.OCIRegion
	}) {
		return fmt.Errorf("%w: initial region intent does not admit anchor cell", ErrBootstrapAnchorInvalid)
	}
	payload, err := trust.EncodePayload(anchor)
	if err != nil {
		return fmt.Errorf("%w: encode anchor: %v", ErrBootstrapAnchorInvalid, err)
	}
	if len(payload) > MaxBootstrapAnchorBytes {
		return fmt.Errorf("%w: anchor exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorBytes)
	}
	return nil

manifest_validate.text:
func (manifest Manifest) validateStructure(derived bool) error {
	ociRegion, err := manifest.Cell.OCIRegion()
	if err != nil || manifest.SchemaVersion != ManifestSchemaVersion || !entityid.Valid(manifest.DeploymentID) ||
		!entityid.Valid(manifest.ClusterID) || manifest.Environment != "production" && manifest.Environment != "canary" ||
		manifest.OCIRegion != ociRegion || manifest.IntentGeneration == 0 || !sha256RE.MatchString(manifest.IntentSHA256) ||
		manifest.ControllerRole != "controller" || !controllerSlotRE.MatchString(manifest.Slot) || !controllerSlotRE.MatchString(manifest.SeedSlot) ||
		!slices.Contains(manifest.ControllerSlots, manifest.Slot) || !slices.Contains(manifest.ControllerSlots, manifest.SeedSlot) ||
		!isOCID(manifest.ImageOCID, "image") || manifest.ImageArchitecture != "linux-amd64" && manifest.ImageArchitecture != "linux-arm64" ||
		!sha256RE.MatchString(manifest.ReleaseReceiptSHA256) || len(manifest.ControllerSlots) == 0 || len(manifest.ControllerSlots) > 64 ||
		len(manifest.Profiles) != len(manifest.ControllerSlots) || len(manifest.Secrets) > 128 {
		return fmt.Errorf("%w: required manifest identity or binding field", ErrManifestInvalid)
	}
	if err := manifest.StorageDomain.Validate(); err != nil {
		return err
	}
	if len(manifest.ControllerConfig) == 0 || len(manifest.ControllerConfig) > MaxControllerConfigBytes ||
		!sha256RE.MatchString(manifest.ControllerConfigSHA256) ||
		digestBytes(manifest.ControllerConfig) != manifest.ControllerConfigSHA256 {
		return fmt.Errorf("%w: controller configuration bytes or digest", ErrManifestInvalid)
	}
	var config map[string]any
	if err := protocol.DecodeStrict(manifest.ControllerConfig, &config, MaxControllerConfigBytes); err != nil ||
		config["nats"] == nil || config["controller"] == nil {
		return fmt.Errorf("%w: controller configuration JSON", ErrManifestInvalid)
	}
	if len(manifest.ControllerFiles) != len(ControllerConfigFileNames) {
		return fmt.Errorf("%w: controller public sidecars are incomplete", ErrManifestInvalid)
	}
	for index, file := range manifest.ControllerFiles {
		if file.Name != ControllerConfigFileNames[index] || len(file.Bytes) == 0 ||
			len(file.Bytes) > MaxControllerSidecarBytes || !sha256RE.MatchString(file.SHA256) ||
			digestBytes(file.Bytes) != file.SHA256 {
			return fmt.Errorf("%w: controller public sidecar %d", ErrManifestInvalid, index)
		}
		var value map[string]any
		if err := protocol.DecodeStrict(file.Bytes, &value, MaxControllerSidecarBytes); err != nil || value == nil {
			return fmt.Errorf("%w: controller public sidecar JSON", ErrManifestInvalid)
		}
	}
	if manifest.ManagedMaterial != nil {
		if err := manifest.ManagedMaterial.Validate(); err != nil {
			return err
		}
	}
	if err := validateReleaseProofWires(manifest); err != nil {
		return err
	}
	if hasDuplicate(manifest.ControllerSlots) || !slices.IsSorted(manifest.ControllerSlots) {
		return fmt.Errorf("%w: controller slot list is duplicated or not sorted", ErrManifestInvalid)
	}
	profiles := make(map[string]struct{}, len(manifest.Profiles))
	for _, profile := range manifest.Profiles {
		if err := profile.validate(); err != nil {
			return err
		}
		if !slices.Contains(manifest.ControllerSlots, profile.Slot) {
			return fmt.Errorf("%w: launch profile slot is not authorized", ErrManifestInvalid)
		}
		if _, exists := profiles[profile.Slot]; exists {
			return fmt.Errorf("%w: duplicate launch profile slot", ErrManifestInvalid)
		}
		profiles[profile.Slot] = struct{}{}
	}
	for _, slot := range manifest.ControllerSlots {
		if _, exists := profiles[slot]; !exists {
			return fmt.Errorf("%w: controller slot has no launch profile", ErrManifestInvalid)
		}
	}
	secretFiles := make(map[string]struct{}, len(manifest.Secrets))
	for _, secret := range manifest.Secrets {
		if err := secret.validate(manifest); err != nil {
			return err
		}
		if _, exists := secretFiles[secret.TargetFile]; exists {
			return fmt.Errorf("%w: duplicate secret output file", ErrManifestInvalid)
		}
		secretFiles[secret.TargetFile] = struct{}{}
	}
	peerSlots := slices.DeleteFunc(slices.Clone(manifest.ControllerSlots), func(slot string) bool { return slot == manifest.SeedSlot })
	if derived && manifest.PeerReceiptDelegation != nil || !derived && (len(peerSlots) == 0 && manifest.PeerReceiptDelegation != nil || len(peerSlots) > 0 && manifest.PeerReceiptDelegation == nil) {
		return fmt.Errorf("%w: peer signer delegation must exactly match peer slot presence", ErrManifestInvalid)
	}
	payload, err := trust.EncodePayload(manifest)
	if err != nil {
		return fmt.Errorf("%w: encode manifest: %v", ErrManifestInvalid, err)
	}
	if len(payload) > MaxManifestBytes {
		return fmt.Errorf("%w: manifest exceeds its size limit", ErrManifestInvalid)
	}
	return nil
}

receipt_sign.text:
func SignImageReceipt(receipt ImageReceipt, environment string, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := validateEnvironment(environment); err != nil {
		return trust.Envelope{}, err
	}
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and at most %s", MaxReceiptLifetime)
	}
	productionExpiry, err := verifyImageProduction(receipt, environment, roots, now)
	if err != nil {
		return trust.Envelope{}, err
	}
	if validFor > 0 && productionExpiry.Before(now.Add(validFor)) {
		validFor = productionExpiry.Sub(now)
	}
	return signReceipt(receipt, ImageScope(receipt, environment), delegation, roots, privateKey, now, validFor)
}

receipt_verify.text:
func VerifyImageCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected ImageExpectation, now time.Time,
) (VerifiedImage, error) {
	if err := validateImageExpectation(expected); err != nil {
		return VerifiedImage{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return VerifiedImage{}, err
	}
	receipt, err := decodeCanonicalPayload[ImageReceipt](envelope.Payload)
	if err != nil {
		return VerifiedImage{}, err
	}
	if err := receipt.Validate(); err != nil {
		return VerifiedImage{}, err
	}
	if err := matchImageExpectation(receipt, expected); err != nil {
		return VerifiedImage{}, err
	}
	scope := ImageScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current signed image receipt: %w", err)
	}
	productionExpiry, err := verifyImageProduction(receipt, expected.Environment, roots, now)
	if err != nil {
		return VerifiedImage{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedImage{}, err
	}
	if productionExpiry.Before(proof.expiresAt) {
		proof.expiresAt = productionExpiry
	}
	return VerifiedImage{receipt: receipt, proof: proof}, nil
}

receipt_expiry.text:
func signReceipt(payload any, scope trust.Scope, delegationEnvelope trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and no longer than %s", MaxReceiptLifetime)
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		expiresAt = delegationEnvelope.ExpiresAt
	}
	if !expiresAt.After(now) {
		return trust.Envelope{}, trust.ErrExpired
	}
	encodedPayload, err := trust.EncodePayload(payload)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(encodedPayload, scope, now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return trust.Envelope{}, fmt.Errorf("release signer is not delegated for this exact scope: %w", err)
	}
	return envelope, nil
}

